/**
 * Turning a publisher's caption file into segments.
 *
 * Two formats carry essentially all real-world podcast transcripts: WebVTT
 * (what `<podcast:transcript>` recommends) and SRT (what everyone's existing
 * tooling already emitted). They differ in three details — a header line, a
 * numeric counter, and a comma instead of a full stop in the timestamp — so
 * they share one parser rather than two that drift.
 *
 * The governing assumption is that these files are *bad*. They are generated by
 * a dozen different tools, hand-edited, truncated by a bad upload, and served
 * with the wrong content type. A parser that throws on the first malformed cue
 * loses a two-hour transcript over one broken line, so every cue is recovered
 * independently and anything unreadable is dropped.
 */

import type { TranscriptSegment } from '@cue/types';

/** `00:01:02.345`, `01:02.345`, `00:01:02,345` — hours optional, comma or dot. */
const TIMESTAMP = /(?:(\d+):)?(\d{1,2}):(\d{2})[.,](\d{1,3})/;

const CUE_RANGE = new RegExp(`^\\s*${TIMESTAMP.source}\\s*-->\\s*${TIMESTAMP.source}`);

/**
 * A WebVTT voice span: `<v Alice>text</v>`, or the informal `Alice: text` that
 * most human-edited files use instead.
 */
const VOICE_TAG = /^<v\s+([^>]+)>\s*/i;
const SPEAKER_PREFIX = /^([A-Z][\w.'-]*(?: [A-Z][\w.'-]*){0,2}):\s+/;

/** Any remaining markup. VTT allows `<i>`, `<b>`, `<c.classname>` and friends. */
const TAGS = /<\/?[^>]+>/g;

function toMs(hours: string | undefined, minutes: string, seconds: string, fraction: string): number {
  // A 2-digit fraction means centiseconds, a 1-digit means tenths. Treating
  // them all as milliseconds would put a cue 900ms early.
  const millis = Number(fraction.padEnd(3, '0'));
  return (
    Number(hours ?? 0) * 3_600_000 + Number(minutes) * 60_000 + Number(seconds) * 1000 + millis
  );
}

/**
 * Split into cue blocks.
 *
 * Blank-line separated, tolerant of CRLF and of the stray whitespace-only lines
 * that hand-editing leaves behind.
 */
function blocksOf(text: string): string[] {
  return text
    .replace(/\r\n?/g, '\n')
    // Byte-order mark. Windows tooling emits it constantly and it would
    // otherwise glue itself to the front of the first cue's text.
    .replace(/^\uFEFF/, '')
    .split(/\n\s*\n/)
    .map((block) => block.trim())
    .filter(Boolean);
}

function cleanText(lines: string[]): { text: string; speaker: string | null } {
  let speaker: string | null = null;
  const first = lines[0] ?? '';

  const voice = VOICE_TAG.exec(first);
  if (voice?.[1]) {
    speaker = voice[1].trim();
    lines = [first.replace(VOICE_TAG, ''), ...lines.slice(1)];
  } else {
    const prefixed = SPEAKER_PREFIX.exec(first);
    if (prefixed?.[1]) {
      speaker = prefixed[1].trim();
      lines = [first.replace(SPEAKER_PREFIX, ''), ...lines.slice(1)];
    }
  }

  const text = lines
    .join(' ')
    .replace(TAGS, '')
    // A caption file wraps for a video overlay, not for reading. Collapsing the
    // wrapping is what turns it back into prose.
    .replace(/\s+/g, ' ')
    .trim();

  return { text, speaker };
}

/**
 * Parse WebVTT or SRT into ordered segments.
 *
 * Format is detected from the content rather than trusted from the `type`
 * attribute or the response header, both of which are wrong often enough that
 * relying on them would drop real transcripts. The shapes are unambiguous
 * anyway — every cue carries its own `-->` line.
 */
export function parseTranscript(source: string): TranscriptSegment[] {
  const segments: TranscriptSegment[] = [];

  for (const block of blocksOf(source)) {
    const lines = block.split('\n');

    // Find the timing line. SRT puts a counter above it, VTT may put a cue
    // identifier there, and the WEBVTT header block has none at all.
    const timingAt = lines.findIndex((line) => CUE_RANGE.test(line));
    if (timingAt === -1) continue;

    const match = CUE_RANGE.exec(lines[timingAt]!);
    if (!match) continue;

    const startMs = toMs(match[1], match[2]!, match[3]!, match[4]!);
    const endMs = toMs(match[5], match[6]!, match[7]!, match[8]!);

    // A cue that ends before it starts is corrupt. Keeping it would break the
    // binary search that finds the active line.
    if (endMs < startMs) continue;

    const { text, speaker } = cleanText(lines.slice(timingAt + 1));
    if (!text) continue;

    segments.push({ index: segments.length, startMs, endMs, text, ...(speaker ? { speaker } : { speaker: null }) });
  }

  // Sort defensively rather than trusting file order: a concatenated or
  // re-timed transcript can arrive out of order, and every consumer downstream
  // assumes ascending starts.
  segments.sort((a, b) => a.startMs - b.startMs);

  return segments.map((segment, index) => ({ ...segment, index }));
}

/** Whether a body looks like captions at all, before we spend a parse on it. */
export function looksLikeTranscript(source: string): boolean {
  return CUE_RANGE.test(source) || /-->/.test(source);
}

// ------------------------------------------------------------------ html --

/**
 * HTML transcripts, which is what publishers actually ship.
 *
 * Worth stating plainly, because it decides what this feature can be: across
 * the whole seeded catalogue, every single `<podcast:transcript>` is
 * `text/html` and not one is VTT or SRT. The spec permits both; the ecosystem
 * chose the one without timings.
 *
 * So these have **no timecodes at all** — they are prose with speaker labels,
 * in the shape Changelog and most others emit:
 *
 *     <cite>Jerod Santo:</cite>
 *     <p>What up, nerds?</p>
 *
 * They can be read. They cannot drive a highlight or a click-to-seek, and
 * pretending otherwise by inventing timings would put the reader's eye in the
 * wrong place and make every jump land somewhere arbitrary. The segments below
 * carry zero timings and the caller marks the transcript untimed, so the UI can
 * offer reading without offering following.
 */
const HTML_ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  '#39': "'",
  apos: "'",
  nbsp: ' ',
};

/**
 * `[label](https://…)` → `label`.
 *
 * Several publishers put Markdown source inside their HTML transcript. Left
 * alone the URL sits in the middle of the sentence as if it had been read out,
 * which is both unreadable and wrong about what was said — the words spoken
 * were the label.
 */
function flattenMarkdownLinks(text: string): string {
  return text.replace(/\[([^\]]+)\]\((?:[^)\s]+)(?:\s+"[^"]*")?\)/g, '$1');
}

function decodeEntities(text: string): string {
  return flattenMarkdownLinks(text)
    .replace(/&(#\d+|#x[0-9a-f]+|[a-z]+);/gi, (whole, name: string) => {
      const named = HTML_ENTITIES[name.toLowerCase()];
      if (named) return named;
      if (name.startsWith('#x') || name.startsWith('#X')) {
        return String.fromCodePoint(Number.parseInt(name.slice(2), 16));
      }
      if (name.startsWith('#')) return String.fromCodePoint(Number(name.slice(1)));
      return whole;
    })
    .replace(/\s+/g, ' ')
    .trim();
}

export function parseHtmlTranscript(source: string): TranscriptSegment[] {
  // Everything inside <body>, or the whole document if there is no body tag.
  const body = /<body[^>]*>([\s\S]*?)<\/body>/i.exec(source)?.[1] ?? source;

  const segments: TranscriptSegment[] = [];
  let speaker: string | null = null;

  // One pass over the two elements that carry meaning. Anything else — scripts,
  // navigation, a wrapper div — is skipped rather than parsed, which is why
  // this does not need a DOM.
  const blocks = body.matchAll(/<(cite|p)\b[^>]*>([\s\S]*?)<\/\1>/gi);

  for (const [, tag, inner] of blocks) {
    const text = decodeEntities((inner ?? '').replace(TAGS, ''));
    if (!text) continue;

    if (tag!.toLowerCase() === 'cite') {
      // `Jerod Santo:` — the colon belongs to the layout, not to the name.
      speaker = text.replace(/:\s*$/, '');
      continue;
    }

    segments.push({
      index: segments.length,
      startMs: 0,
      endMs: 0,
      text,
      speaker,
    });

    // A speaker label introduces the paragraphs that follow it until the next
    // label, so it is deliberately not cleared here.
  }

  return segments;
}

/** HTML transcripts carry no timings, so nothing can follow the audio. */
export function isTimed(segments: TranscriptSegment[]): boolean {
  return segments.some((segment) => segment.endMs > 0);
}
